import { Button } from "@/components/ui/button";

import { ButtonIcon } from "./parts/button-icon";
import { ButtonLabel } from "./parts/button-label";

export default function Button03() {
  return (
    <Button>
      <ButtonLabel>Explore components</ButtonLabel>
      <ButtonIcon />
    </Button>
  );
}

import { ArrowRightIcon } from "lucide-react";

export function ButtonIcon() {
  return <ArrowRightIcon aria-hidden="true" data-icon="inline-end" />;
}

import type { ReactNode } from "react";

export function ButtonLabel({ children }: { children: ReactNode }) {
  return <span>{children}</span>;
}
